const j=$json;
return [{json:{
  status:String(j.status??'error'),
  worker:String(j.worker??'PEDIDOS'),
  respuesta:String(j.respuesta??'No pude completar el pedido. No se registró.'),
  requires_human:Boolean(j.requires_human),
  pedido_registrado:Boolean(j.pedido_registrado),
  evidence:Array.isArray(j.evidence)?j.evidence:[],
  human_decision:String(j.human_decision??''),
}}];

const raw=$json.output??$json.text??$json.response??'';
const input=String($('Start').first().json.original_input??'');
const human_decision=String($('Start').first().json.human_decision??'');
let result;
try {
  result=typeof raw==='object'&&raw!==null?raw:JSON.parse(String(raw).replace(/^```json\s*/i,'').replace(/```$/,'').trim());
} catch(error) {
  return {json:{status:'error',worker:'PEDIDOS',requires_human:true,respuesta:'No pude validar el pedido con seguridad y no lo registré. Una persona revisará la solicitud.',evidence:[],human_decision}};
}
function isError(value) {
  if (value && typeof value==='object' && !Array.isArray(value) && (value.error || value.success===false)) return true;
  const text=typeof value==='string'?value:JSON.stringify(value??'');
  return /^\s*(error|failed|failure)\b/i.test(text) || /\b(no output data|no rows returned)\b/i.test(text);
}
function isRow(value) {
  return Boolean(value&&typeof value==='object'&&!Array.isArray(value)&&Object.keys(value).length&&!isError(value));
}
function rowsFromObservation(observation,depth=0) {
  if(depth>6||observation==null||isError(observation)) return [];
  let value=observation;
  if(typeof value==='string') {
    try { value=JSON.parse(value); } catch { return []; }
  }
  if(Array.isArray(value)) return value.flatMap(item=>rowsFromObservation(item,depth+1));
  if(!value||typeof value!=='object') return [];
  const keys=Object.keys(value);
  if(keys.length===1&&['response','output','json'].includes(keys[0])) return rowsFromObservation(value[keys[0]],depth+1);
  for(const key of ['data','results','rows']) {
    if(keys.length<=2&&value[key]!==undefined) return rowsFromObservation(value[key],depth+1);
  }
  return isRow(value)?[value]:[];
}
const evidence=[];
for (const step of Array.isArray($json.intermediateSteps)?$json.intermediateSteps:[]) {
  const tool=String(step?.action?.tool??'');
  if (tool!=='Menu_Google_Sheets1') continue;
  for (const row of rowsFromObservation(step.observation)) evidence.push({source:tool,quote:JSON.stringify(row)});
}
const evidenceValid=evidence.length>0;
const requestedHuman=Boolean(result.requires_human);
const order=result.pedido&&typeof result.pedido==='object'?result.pedido:{};
const explicit=/^\s*CONFIRMO PEDIDO:/.test(input);
const name=String(order.Nombre_Cliente??'').trim();
const phone=String(order.Contacto_Telefono??'').trim();
const email=String(order.Correo_Electronico??'').trim();
const details=String(order.Pedido_Detalle??'').trim();
const contact=Boolean(phone||email);
const ready=explicit&&result.registro_solicitado===true&&!requestedHuman&&Boolean(name)&&contact&&Boolean(details)&&evidenceValid;
if(ready) {
  order.Fecha_Hora=new Date().toISOString();
  order.Canal=String($('Start').first().json.canal??'');
  order.Estado='Pendiente';
  order.Notas_Especiales=String(order.Notas_Especiales??'No informado').trim()||'No informado';
  return {json:{pedido_listo:true,status:'pending_write',worker:'PEDIDOS',requires_human:false,pedido:order,respuesta:'',evidence,human_decision}};
}
let reason='';
if(requestedHuman) reason='La solicitud requiere revisión humana; no registré el pedido.';
else if(!evidenceValid) reason='No pude verificar los productos con evidencia del menú, por lo que no registré el pedido.';
else if(!explicit) reason='Para evitar registros por error, todavía no registré el pedido.';
else if(!name) reason='Falta el nombre de quien realiza el pedido.';
else if(!contact) reason='Falta un teléfono o correo electrónico de contacto.';
else if(!details) reason='No pude confirmar los productos y cantidades.';
else reason='No pude verificar el pedido con seguridad.';
const confirmation=details?` Si está correcto, reenvíalo completo con el prefijo exacto CONFIRMO PEDIDO: ${details}, tu nombre y un teléfono o correo.`:' Reenvía el detalle completo del pedido con el prefijo exacto CONFIRMO PEDIDO:, tu nombre y un teléfono o correo.';
return {json:{pedido_listo:false,status:'awaiting_confirmation',worker:'PEDIDOS',requires_human:requestedHuman||!evidenceValid,pedido:order,respuesta:`${reason}${confirmation}`,evidence,human_decision}};

const order=$('Pedido - Validar confirmación y preparar registro').first().json.pedido;
const validation=$('Pedido - Validar confirmación y preparar registro').first().json;
const result=$json;
const resultQuote=result&&typeof result==='object'&&Object.keys(result).length?JSON.stringify(result):'';
const resultText=typeof result==='string'?result:resultQuote;
const failed=result&&typeof result==='object'&&(result.error||result.success===false) || /^\s*(error|failed|failure)\b/i.test(resultText) || /\b(no output data|no rows returned)\b/i.test(resultText);
if(!resultQuote||failed) return {json:{status:'needs_human',worker:'PEDIDOS',requires_human:true,respuesta:'El paso de registro terminó, pero no recibí una fila que permita verificar el resultado. No reenvíes el pedido hasta que una persona compruebe si quedó registrado.',pedido_registrado:false,evidence:validation.evidence,human_decision:validation.human_decision}};
const evidence=[...validation.evidence,{source:'Pedidos - Registrar confirmación explícita',quote:resultQuote}];
return {json:{status:'success',worker:'PEDIDOS',requires_human:false,respuesta:`Tu pedido de ${order.Pedido_Detalle} quedó registrado.`,pedido_registrado:true,evidence,human_decision:validation.human_decision}};
